void selecao(vector<int> &v) {
    int n = static_cast<int>(v.size());
    for (int i = 0; i < n - 1; i++) {
        int menor = i;
        for (int j = i + 1; j < n; j++) {  // o menor do resto
            if (v[j] < v[menor]) menor = j;
        }
        swap(v[i], v[menor]);              // uma troca só
    }
}

