void insercao(vector<int> &v) {
    int n = static_cast<int>(v.size());
    for (int i = 1; i < n; i++) {
        int chave = v[i];        // o próximo a ser inserido
        int j = i - 1;
        while (j >= 0 && v[j] > chave) {
            v[j + 1] = v[j];     // desloca o maior à direita
            j--;
        }
        v[j + 1] = chave;        // encaixa no espaço aberto
    }
}

